// The licence manifest (assets/audio/LICENSES.md, FX-05) read by the application: #/sons shows the
// author and licence of each sound, and the « Crédits et licences » sheet lists every row. The
// markdown file is the single source; cells are only ever shown as text.

import manifest from "../../../../assets/audio/LICENSES.md?raw";

export type LicenceRow = {
  /** Sound id for a sound, otherwise a short key (nunito, lucide, plateau…). */
  id: string;
  /** File names, or « — » when the asset is generated by code. */
  fichier: string;
  /** « son », « police », « icônes », « plateau », « cavaliers » or « cartes ». */
  type: string;
  source: string;
  auteur: string;
  licence: string;
  /** Address of the original page, or « — ». */
  url: string;
};

const COLUMNS = ["id", "fichier", "type", "source", "auteur", "licence", "url"] as const;

function cellsOf(line: string): string[] {
  let text = line.trim();
  if (text.startsWith("|")) text = text.slice(1);
  if (text.endsWith("|")) text = text.slice(0, -1);
  return text.split("|").map((cell) => cell.trim());
}

const isSeparator = (cells: string[]) => cells.every((cell) => /^:?-+:?$/.test(cell));

/**
 * Rows of the first Markdown table of `markdown`. The header row and the separator row are skipped,
 * cells are trimmed, and a row shorter than the header gets empty strings for the missing cells.
 */
export function parseLicences(markdown: string): LicenceRow[] {
  const lines = markdown.split(/\r?\n/);
  const rows: LicenceRow[] = [];
  let index = 0;
  // The table starts at a line with a pipe that is followed by a separator row (prose with a pipe
  // in it does not open a table).
  while (index < lines.length) {
    const line = lines[index] ?? "";
    const next = lines[index + 1] ?? "";
    if (line.includes("|") && next.includes("|") && isSeparator(cellsOf(next))) break;
    index++;
  }
  // Skip the header row and the separator row, then read rows until the first line without a pipe.
  for (index += 2; index < lines.length; index++) {
    const line = lines[index] ?? "";
    if (!line.includes("|")) break;
    const cells = cellsOf(line);
    if (isSeparator(cells)) continue;
    const row = Object.fromEntries(
      COLUMNS.map((name, column) => [name, cells[column] ?? ""]),
    ) as LicenceRow;
    if (row.id !== "") rows.push(row);
  }
  return rows;
}

/** Every row of assets/audio/LICENSES.md. */
export const LICENCES: LicenceRow[] = parseLicences(manifest);

/** The row of one asset, by id (a sound id for a sound). */
export function licenceOf(id: string): LicenceRow | undefined {
  return LICENCES.find((row) => row.id === id);
}
